local _, WFJ = ...
WFJ.Data.add("book", {
  ["6801a4d3ae4a60be"] = { "{name}, spero che questa lettera ti trovi bene. Dopo qualche ricerca, ho scoperto alcune informazioni su chi ha scritto il biglietto che hai recuperato.\n\nIl padre di Samla guida i Reietti e i troll che compiono il pellegrinaggio al ⟦Thunder Bluff=Picco del Tuono⟧ secondo i precetti della sua fede. Si chiama Miles Welsh e lo trovi insieme ad altri non morti nelle Pozze delle Visioni.\n\nTorgal, invece, ha lasciato una cugina, Elissa Dumas. Da quanto ho capito, è una persona riservata; passa le giornate nel ⟦Temple of the Moon=Tempio della Luna⟧, a Darnassus.\n\nTi esorto a far visita a chi puoi, {name}. Forse non hanno mai saputo quale sorte sia toccata a Torgal o a Samla.", "." },
  ["68128df4cc234432"] = { "IV. Controlli di flusso\n\nAumentano o diminuiscono la portata. Questa è regolata automaticamente dal meccanismo di controllo del samoflago.\n\nV. Indicatore di temperatura\n\nMostra la temperatura di esercizio del sistema in generale.", "." },
  ["687572aba1973e8c"] = { "Per alimentare i nuovi portali, gli servivano alcuni manufatti incantati di Azeroth. Per procurarseli, Ner'zhul riaprì il Portale Oscuro e vi lanciò attraverso i suoi famelici servitori.", "." },
  ["688b27b5b5d6fad7"] = { "<HTML>\n<BODY>\n<BR/>\n<BR/>\n<P>\nIn memoria del mio caro mentore, Horatio M. Montgomery, M.D. Guaritore, maestro, amico.\n</P>\n<BR/>\n<H1 align=\"center\">\n50 BTFT - 25 ATFT\n</H1>\n<BR/>\n<P>\n«Il mondo è pieno di malati e di sfiniti. È nostro compito, come guaritori, ANZI, come uomini e donne di medicina, liberarli TUTTI dalla \"-ite\".» \n</P>\n<BR/>\n<P>\n- H.M.M., M.D., PhD, JD, Gran Maestro Contadino, Ballerino Straordinario, Amico degli Animali\n</P>\n<BR/>\n</BODY>\n</HTML>", "." },
  ["68c94213ba386d62"] = { "Qui sotto troverai ciò che serve al mio incantesimo per evocare il grande Ciclonian. Che la fortuna ti accompagni.\n\n--Bath'rah l'osservatore dei venti", "." },
  ["68d843de3ca22505"] = { "Ajeck e Sir Erlgadin stavano pronti, i fucili puntati sulla vegetazione irta alla base degli alberi ondeggianti. Il sole di mezzogiorno ci batteva addosso. Un lento rivolo di sudore scese dalla tempia di Elrgadin mentre tirava indietro il cane. Al suono dello scatto, il fitto fogliame si aprì e una grossa pantera nera, uno splendido esemplare, schizzò fuori nella radura.", "." },
  ["68fd21d85a1e1939"] = { "Delle due razze, Kil'jaeden vide che gli orchi guerrieri erano più vulnerabili alla corruzione della Legione. Soggiogò l'anziano sciamano degli orchi, Ner'zhul, più o meno come Sargeras aveva posto sotto il suo controllo la regina Azshara in ere passate. Usando l'astuto sciamano come tramite, il demone diffuse la sete di battaglia e la ferocia tra i clan degli orchi.", "." },
})
